CREATE TABLE IF NOT EXISTS construction_intelligence.expense_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_ref uuid NOT NULL, expense_ref uuid NOT NULL, storage_ref varchar(500) NOT NULL, filename varchar(200) NOT NULL, content_type varchar(100) NOT NULL, size_bytes bigint NOT NULL DEFAULT 0, visible_to_owner boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now())
